import openpyxl
wb = openpyxl.load_workbook('/home/user/Documents/Finance/tally_book.xlsx')
for sn in wb.sheetnames:
    ws = wb[sn]
    print('Sheet:', sn, 'dims:', ws.dimensions, 'max_row:', ws.max_row, 'max_col:', ws.max_column)
    for row in ws.iter_rows(values_only=False):
        for cell in row:
            if cell.value is not None:
                print(f'  {cell.coordinate}: {cell.value!r} (style={cell.number_format})')
"
